<?php require __DIR__.'/../includes/auth.php';require __DIR__.'/../config/database.php'; if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare("INSERT INTO services(title,description) VALUES(?,?)");$s->execute([$_POST['title'],$_POST['description']]);} $rows=$pdo->query("SELECT * FROM services ORDER BY id DESC")->fetchAll();?><!doctype html><html><head><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-slate-100 p-8"><main class="mx-auto max-w-5xl"><h1 class="text-3xl font-black">Services</h1><form method="post" class="mt-6 rounded-2xl bg-white p-6 flex gap-3"><input class="border rounded-lg p-3" name="title" placeholder="Title" required><input class="border rounded-lg p-3 flex-1" name="description" placeholder="Description" required><button class="rounded-lg bg-blue-600 px-5 text-white">Add</button></form><div class="mt-6 rounded-2xl bg-white p-6"><?php foreach($rows as $r):?><p class="border-b py-3"><b><?=$r['title']?></b> — <?=$r['description']?></p><?php endforeach;?></div></main></body></html>